async () => {
  const out = [];
  let doc = document;
  for (let p = 1; p <= 17; p++) {
    if (p > 1) {
      const f = document.forms[0];
      const fd = new FormData(f);
      fd.set('__EVENTTARGET', 'gv'); fd.set('__EVENTARGUMENT', 'Page$' + p);
      const r = await fetch(location.href, {method:'POST', body:new URLSearchParams(fd)});
      doc = new DOMParser().parseFromString(await r.text(), 'text/html');
    }
    [...doc.querySelectorAll('tr')].map(r=>r.innerText?.replace(/\s+/g,' ').trim() ?? r.textContent.replace(/\s+/g,' ').trim()).filter(t=>/^\d+ D\d+/.test(t)).forEach(t=>out.push(p+': '+t));
  }
  return out.filter(t=>/ 10(04|11|26) /.test(t));
}

