async () => {
  const out = [];
  for (let p = 1; p <= 17; p++) {
    const fd = new FormData(document.forms[0]);
    fd.set('__EVENTTARGET', 'gv'); fd.set('__EVENTARGUMENT', 'Page$' + p);
    const t = await (await fetch(location.href, {method:'POST', body:new URLSearchParams(fd)})).text();
    const d = new DOMParser().parseFromString(t, 'text/html');
    d.querySelectorAll('tr').forEach(r => { const c=[...r.children].map(x=>x.textContent.trim()); if (/^D\d+$/.test(c[1]||'')) out.push(p+': '+c.slice(0,4).join(' | ')); });
  }
  return {total: out.length, hits: out.filter(t=>/\| 10(04|11|26) \|/.test(t))};
}

